package ru.truetv.bridge;
import java.io.*;import java.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Real TLS for standalone shared text, distinct from ordinary TXT and no Android claims. */
public final class TextTransferCheck {
 static int checks;static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);checks++;}interface Run{void run()throws Exception;}static void rejected(Run r)throws Exception{try{r.run();throw new AssertionError("Expected rejection");}catch(IOException good){checks++;}}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory("totv-text-test");Identity tv=Identity.load(root.resolve("tv").toFile()),phone=Identity.load(root.resolve("phone").toFile());AtomicReference<String> result=new AtomicReference<>();AtomicInteger fileTargets=new AtomicInteger();CountDownLatch finished=new CountDownLatch(1);
  Transfer.Receiver receiver=new Transfer.Receiver(tv,"TV",item->{if(SharedText.MIME.equals(item.mime))return SharedText.target(item,result::set);fileTargets.incrementAndGet();throw new IOException("No file expected");},(offer,fp,code)->SharedText.isText(offer),new Transfer.Events(){public void update(int i,String n,long b,long t){}public void finished(boolean ok,String detail){finished.countDown();}});
  Thread server=new Thread(()->{try{receiver.accept();}catch(IOException ignored){}});server.start();Transfer.ClientEvents quiet=new Transfer.ClientEvents(){public void waiting(String n,String fp,String c){}public void accepted(String fp){}public void update(int i,String n,long b,long t){}};
  String[] values={"vless://fixture@example.invalid:443?security=tls&x=+%2F#Тест","https://example.invalid/path?a=1&b=2#фрагмент"," 00123-ABC\r\nРусский 😀\n\t ","",new String(new char[SharedText.MAX_BYTES]).replace('\0','a')};
  for(String value:values){byte[] bytes=SharedText.encode(value);Wire.Offer offer=new Wire.Offer("Phone",Arrays.asList(SharedText.item(bytes)));check(SharedText.isText(offer),"explicit text marker");new Transfer.Sender().send(phone,InetAddress.getLoopbackAddress(),receiver.port(),tv.fingerprint(),offer,i->new ByteArrayInputStream(bytes),quiet);check(value.equals(result.get()),"exact plaintext over TLS");}
  check(fileTargets.get()==0,"text never enters file store");check(!SharedText.isText(new Wire.Offer("Phone",Arrays.asList(new Wire.Item("notes.txt","text/plain",1)))),"real TXT file stays a file");
  rejected(()->SharedText.encode(new String(new char[SharedText.MAX_BYTES+1])));rejected(()->SharedText.encode("\ud800"));rejected(()->SharedText.isText(new Wire.Offer("Phone",Arrays.asList(new Wire.Item("bad",SharedText.MIME,-1)))));rejected(()->SharedText.isText(new Wire.Offer("Phone",Arrays.asList(new Wire.Item("bad",SharedText.MIME,SharedText.MAX_BYTES+1)))));rejected(()->SharedText.isText(new Wire.Offer("Phone",Arrays.asList(SharedText.item(new byte[1]),new Wire.Item("file.bin","application/octet-stream",1)))));
  Wire.Target invalid=SharedText.target(SharedText.item(new byte[2]),x->{throw new AssertionError("Invalid UTF-8 exposed");});invalid.stream().write(new byte[]{(byte)0xc3,0x28});rejected(invalid::publish);invalid.discard();Wire.Target overflow=SharedText.target(SharedText.item(new byte[0]),x->{throw new AssertionError();});rejected(()->overflow.stream().write(new byte[SharedText.MAX_BYTES+1]));overflow.discard();
  receiver.close();server.join(3000);try(java.util.stream.Stream<Path> all=Files.walk(root)){all.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new RuntimeException(e);}});}System.out.println("PASS "+checks+" shared-text exact TLS/UTF8/limits/file-separation checks");
 }
}
